// Block (composition) — a titled group of controls, spaced so each control reads as its own and the group as one.
// Arranges only; composes Stack. The controls are the consumer's (Slider · Select · TextField …).
//
// Why a Block and not the consumer's own markup: the theme studio wrote this arrangement out by
// hand, and a spacing fix had to reach every copy: the helpers got it and the groups written out by
// hand did not. `studio-contract.md` rule 6 files that as a gap in the
// system, not in the studio.
//
// The gaps are derived, not chosen, by the two laws in `token-contract.md` § By relationship, and
// they follow `size` because the Slider gap they are derived from does. Controls are
// parted two rungs over the gap a Slider of that size uses between its own label, track and
// description (`slider.gap.<size>`: x-small, small, medium), so `medium`, `large`, `x-large`. The
// title is attached to the controls it names, so it sits at their gap and never tighter. Groups
// stacked by a consumer part two rungs over that again; at `large` that is past the ladder's last
// rung, which is why `large` is for a roomy panel with one group, not a stack of them.
import { useId, type ReactNode, type Ref } from "react";

export type ControlGroupSize = "small" | "medium" | "large";
/** The controls' gap at each size: parting, two rungs over `slider.gap.<size>`. */
const GAP = { small: "medium", medium: "large", large: "x-large" } as const;
/** The title, one label rung below the controls' own `label-<size>` (CONTRASTIVE), floored at `small`. */
const TITLE = { small: "small", medium: "small", large: "medium" } as const;
import { Stack } from "../layouts/Stack";
import "./ControlGroup.css";

export interface ControlGroupProps {
  /**
   * The group's label, rendered as a heading that names the section. Omit it when the group sits
   * inside something that already carries the title (a `Collapsible` trigger): an empty heading is
   * a nameless landmark a screen reader announces with nothing to say.
   */
  title?: string;
  /** Heading level for `title`, so the group fits the outline of the page it is placed in. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  /**
   * The size of the controls inside, which the group's spacing follows. Pass the size the controls
   * themselves take; a group of `small` Sliders closes up to `medium` between them.
   *
   * @default "medium"
   */
  size?: ControlGroupSize;
  /** The controls, one per child. */
  children: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ControlGroup({ title, headingLevel = 2, size = "medium", children, className, ref }: ControlGroupProps) {
  const titleId = useId();
  const Heading = `h${headingLevel}` as const;
  return (
    <Stack
      as="section"
      ref={ref}
      direction="column"
      gap={GAP[size]}
      aria-labelledby={title ? titleId : undefined}
      className={className ? `sd-controlgroup ${className}` : "sd-controlgroup"}
    >
      {/* One rung below the controls' own labels, `label-<size>`: CONTRASTIVE, the two are read
          together, and a group title at the same size reads as one more control's label with
          nothing under it. `small` is the floor, where the two share a rung. The role stays `label`
          because it names a group of controls, not a page section. */}
      {title && (
        <>
          <Heading id={titleId} className={`sd-controlgroup__title sd-type-label-${TITLE[size]}`}>
            {title}
          </Heading>
        </>
      )}
      <Stack direction="column" gap={GAP[size]} className="sd-controlgroup__controls">
        {children}
      </Stack>
    </Stack>
  );
}

/* ControlGroup.css — .sd-controlgroup (Block)
   Arrangement only: the Block's two gaps (title to controls, control to control) are Stack props
   in ControlGroup.tsx, and the controls own their own look. The gap between one group and the next
   is the consumer's, which ControlGroup.tsx's header derives. The one rule here resets the heading's user-agent margin, which would otherwise add to
   the title gap the arrangement derives. */
.sd-controlgroup__title {
  margin: 0;
}
